import { PrismaClient } from '@prisma/client';

export type CheckStatus = 'ok' | 'mock' | 'error' | 'skipped';

export type HealthCheck = {
  status: CheckStatus;
  message?: string;
  latencyMs?: number;
};

export type HealthChecks = {
  app: HealthCheck;
  database: HealthCheck;
  moviebox: HealthCheck;
  ai: HealthCheck;
};

export type OverallStatus = 'ok' | 'degraded' | 'error';

const PROBE_TIMEOUT_MS = 3000;

async function checkDatabase(): Promise<HealthCheck> {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    return {
      status: 'mock',
      message: 'DATABASE_URL not set; using mock db',
    };
  }

  const start = Date.now();
  const prisma = new PrismaClient();

  try {
    await prisma.$queryRaw`SELECT 1`;
    return {
      status: 'ok',
      latencyMs: Date.now() - start,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Database connection failed';
    return {
      status: 'error',
      message,
      latencyMs: Date.now() - start,
    };
  } finally {
    await prisma.$disconnect();
  }
}

async function probeUrl(url: string): Promise<Response> {
  return fetch(url, {
    signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
    cache: 'no-store',
  });
}

async function checkMoviebox(): Promise<HealthCheck> {
  const baseUrl = process.env.MOVIEBOX_API_URL ?? 'http://127.0.0.1:8000';
  const start = Date.now();

  try {
    const healthUrl = new URL('/health', baseUrl).toString();
    const healthResponse = await probeUrl(healthUrl);

    if (healthResponse.ok) {
      return {
        status: 'ok',
        latencyMs: Date.now() - start,
      };
    }

    if (healthResponse.status !== 404) {
      return {
        status: healthResponse.status < 500 ? 'ok' : 'error',
        message:
          healthResponse.status >= 500
            ? `Moviebox returned ${healthResponse.status}`
            : undefined,
        latencyMs: Date.now() - start,
      };
    }

    const rootResponse = await probeUrl(new URL('/', baseUrl).toString());
    const reachable = rootResponse.status < 500;

    return {
      status: reachable ? 'ok' : 'error',
      message: reachable ? undefined : `Moviebox returned ${rootResponse.status}`,
      latencyMs: Date.now() - start,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Moviebox unreachable';
    return {
      status: 'error',
      message,
      latencyMs: Date.now() - start,
    };
  }
}

function checkAi(): HealthCheck {
  const providers: string[] = [];

  if (process.env.OPENROUTER_API_KEY) {
    providers.push('openrouter');
  }

  if (process.env.NVAPI_API_KEY) {
    providers.push('nvapi');
  }

  if (providers.length === 0) {
    return {
      status: 'skipped',
      message: 'No AI keys configured',
    };
  }

  return {
    status: 'ok',
    message: `Configured: ${providers.join(', ')}`,
  };
}

export function computeOverallStatus(checks: HealthChecks): OverallStatus {
  const blockingChecks = [checks.database, checks.moviebox];

  if (blockingChecks.some((check) => check.status === 'error')) {
    return 'error';
  }

  if (checks.database.status === 'mock' || checks.ai.status === 'skipped') {
    return 'ok';
  }

  return 'ok';
}

export async function runHealthChecks(): Promise<HealthChecks> {
  const [database, moviebox] = await Promise.all([checkDatabase(), checkMoviebox()]);

  return {
    app: { status: 'ok' },
    database,
    moviebox,
    ai: checkAi(),
  };
}
